CREATE DATABASE IF NOT EXISTS eglise_germe_de_david CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE eglise_germe_de_david;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(150) NOT NULL,role ENUM('admin','treasurer','viewer') NOT NULL DEFAULT 'viewer',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE settings(setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE accounts(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,description TEXT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,account_id INT NULL,name VARCHAR(120) NOT NULL,kind ENUM('income','expense','both') NOT NULL DEFAULT 'both',UNIQUE KEY uq_category(account_id,name),FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE account_openings(id INT AUTO_INCREMENT PRIMARY KEY,account_id INT NOT NULL,year SMALLINT NOT NULL,currency ENUM('USD','FC') NOT NULL,opening_amount DECIMAL(16,2) NOT NULL DEFAULT 0,UNIQUE KEY uq_opening(account_id,year,currency),FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE transactions(id BIGINT AUTO_INCREMENT PRIMARY KEY,account_id INT NOT NULL,category_id INT NULL,tx_date DATE NOT NULL,type ENUM('income','expense') NOT NULL,currency ENUM('USD','FC') NOT NULL,amount DECIMAL(16,2) NOT NULL,label VARCHAR(180) NOT NULL,description TEXT NULL,created_by INT NULL,updated_by INT NULL,updated_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_tx_date(tx_date),INDEX idx_account_currency(account_id,currency),INDEX idx_account_currency_date(account_id,currency,tx_date),INDEX idx_account_date(account_id,tx_date),FOREIGN KEY(account_id) REFERENCES accounts(id),FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE monthly_inventories(id BIGINT AUTO_INCREMENT PRIMARY KEY,account_id INT NOT NULL,year SMALLINT NOT NULL,month TINYINT NOT NULL,currency ENUM('USD','FC') NOT NULL,opening_amount DECIMAL(16,2) NOT NULL,income DECIMAL(16,2) NOT NULL,expense DECIMAL(16,2) NOT NULL,closing_amount DECIMAL(16,2) NOT NULL,closed_by INT NULL,closed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_inventory(account_id,year,month,currency),FOREIGN KEY(account_id) REFERENCES accounts(id),FOREIGN KEY(closed_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(40) NOT NULL,table_name VARCHAR(80) NOT NULL,record_id BIGINT NULL,details TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
